# ======================# Q1: J medio NFW disco [0°, 1°] + PLOT# ======================import numpy as npimport matplotlib.pyplot as pltfrom scipy.integrate import quad# Costantir_sun = 8.33rho_sun = 0.3r_max = 60.0r_s = 24.42rho_s = 0.184deg_to_rad = np.pi / 180# Geometriadef r_gc(s, theta):    return np.sqrt(r_sun**2 + s**2 - 2*r_sun*s*np.cos(theta))def s_max(theta):    return r_sun*np.cos(theta) + np.sqrt(r_max**2 - (r_sun*np.sin(theta))**2)# Profilodef rho_nfw(r):    r = max(r, 1e-4)  # cutoff per stabilità numerica    return rho_s * (r_s / r) / (1 + r/r_s)**2# J(theta)def J_theta(theta):    smax = s_max(theta)    def integrand(s):        r = r_gc(s, theta)        rho = rho_nfw(r)        return (rho / rho_sun)**2 / r_sun    s0 = r_sun*np.cos(theta)    return quad(integrand, 0, s0)[0] + quad(integrand, s0, smax)[0]# J mediodef J_bar(theta1, theta2):    eps = 1e-6    theta1 = max(theta1, eps)    def integrand(theta):        return np.sin(theta) * J_theta(theta)    num = 2*np.pi * quad(integrand, theta1, theta2)[0]    den = 2*np.pi * (np.cos(theta1) - np.cos(theta2))    return num / den# ===== Calcolo =====theta2 = 1 * deg_to_radJ_result = J_bar(0, theta2)print("=== Q1 ===")print("J medio =", J_result)# ===== PLOT =====angles_deg = np.logspace(-3, 0, 50)angles = angles_deg * deg_to_radJ_values = [J_theta(t) for t in angles]plt.figure()plt.loglog(angles_deg, J_values)plt.xlabel("theta (deg)")plt.ylabel("J(theta)")plt.title("J(theta) NFW")plt.grid()plt.show()